body:
We saw this in production. Not sure what caused Relay to go all "fundefined" but here's the query:

```
query Sidebar_route {
  currentAccount {
    id
    ...Fundefined
  }
}

fragment F0 on Project {
  name
  identifier
  platform
  iconUrl
  organization {
    alias
    name
    id
  }
  id
}

fragment Fundefined on Account {
  _projectsundefinedcqQId: projects(first: 100) {
    pageInfo {
      hasNextPage
      hasPreviousPage
    }
    edges {
      node {
        externalId
        name
        identifier
        platform
        organization {
          name
          alias
          id
        }
        id
        ...F0
      }
      cursor
    }
  }
  id
}

fragment Fundefined on Account {
  id
  ...Fundefined
}
```

